const users = [
  { name: 'Alice', age: 30, active: true,  role: 'admin' },
  { name: 'Bob',   age: 17, active: true,  role: 'user'  },
  { name: 'Carol', age: 25, active: false, role: 'user'  },
  { name: 'Dave',  age: 22, active: true,  role: 'user'  }
];

// ── Imperative style ─────────────────────────────────────────────
// Explicitly loop, mutate accumulator, return result
function getActiveAdultNamesImperative(users) {
  const result = [];
  for (let i = 0; i < users.length; i++) {
    if (users[i].active && users[i].age >= 18) {
      result.push(users[i].name.toUpperCase());
    }
  }
  return result;
}
console.log('Imperative:', getActiveAdultNamesImperative(users));
// ['ALICE', 'DAVE']

// ── OOP style ────────────────────────────────────────────────────
class UserCollection {
  #users;  // private field (encapsulation)
  constructor(users) { this.#users = users; }

  filterActive()     { return new UserCollection(this.#users.filter(u => u.active)); }
  filterAdults()     { return new UserCollection(this.#users.filter(u => u.age >= 18)); }
  mapNames()         { return this.#users.map(u => u.name.toUpperCase()); }
}
const collection = new UserCollection(users);
console.log('OOP:', collection.filterActive().filterAdults().mapNames());
// ['ALICE', 'DAVE']

// ── Functional style ─────────────────────────────────────────────
// Pure functions — no mutations, compose via pipeline
const isActive = u => u.active;
const isAdult  = u => u.age >= 18;
const toUpperName = u => u.name.toUpperCase();

const activeAdultNames = users
  .filter(isActive)
  .filter(isAdult)
  .map(toUpperName);
console.log('Functional:', activeAdultNames);
// ['ALICE', 'DAVE']

// HOF: compose two predicates
const both = (f, g) => x => f(x) && g(x);
const activeAdult = both(isActive, isAdult);
console.log('HOF compose:', users.filter(activeAdult).map(toUpperName));
// ['ALICE', 'DAVE']

// ── Declarative style (SQL equivalent in JS using reduce) ─────────
// Describe WHAT we want, not HOW
const query = {
  where: [u => u.active, u => u.age >= 18],
  select: u => u.name.toUpperCase()
};
const run = ({ where, select }, data) =>
  where.reduce((acc, pred) => acc.filter(pred), data).map(select);
console.log('Declarative:', run(query, users));
// ['ALICE', 'DAVE']

// ── Pure functions vs impure (side effects) ───────────────────────
// PURE — same input, same output, no side effects
const add = (a, b) => a + b;
const double = x => x * 2;
const toUpper = s => s.toUpperCase();

// IMPURE — depends on or mutates external state
let count = 0;
const increment = () => { count++; return count; }; // reads+writes external state
const logAndAdd = (a, b) => { console.log(a, b); return a + b; }; // side effect: I/O

// ── Immutability ──────────────────────────────────────────────────
const original = { name: 'Alice', score: 10 };
// Mutable (imperative):
original.score = 20; // modifies in place — dangerous in shared state

// Immutable (functional):
const updated = { ...original, score: 20 }; // new object, original unchanged
console.log(original.score, updated.score);  // 20 20 (original was mutated above)

// ── Higher-order functions ────────────────────────────────────────
// map, filter, reduce are HOFs built into Array.prototype
const nums = [1, 2, 3, 4, 5];
const evens  = nums.filter(n => n % 2 === 0);          // [2, 4]
const squares = nums.map(n => n * n);                   // [1, 4, 9, 16, 25]
const sum     = nums.reduce((acc, n) => acc + n, 0);    // 15
console.log({ evens, squares, sum });

// ── Function composition ──────────────────────────────────────────
const compose = (...fns) => x => fns.reduceRight((v, f) => f(v), x);
const pipe    = (...fns) => x => fns.reduce((v, f) => f(v), x);

const process = pipe(
  x => x * 2,
  x => x + 1,
  x => `Result: ${x}`
);
console.log(process(5)); // Result: 11

// ── JS multi-paradigm: mixing styles ─────────────────────────────
// OOP class with functional methods inside
class Cart {
  #items;
  constructor() { this.#items = []; }
  add(item)   { return (this.#items = [...this.#items, item], this); } // immutable update
  total()     { return this.#items.reduce((s, i) => s + i.price, 0); }
  summary()   { return this.#items.map(i => i.name).join(', '); }
}
const cart = new Cart();
cart.add({ name: 'Book', price: 15 }).add({ name: 'Pen', price: 2 });
console.log(cart.summary(), '| total:', cart.total());
// Book, Pen | total: 17
